<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) { return defaultValue; }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                return current.join(', ');
            } else { return '无'; }
        }
        if (typeof current === 'boolean') { return current; }
        return current;
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValue, min = 0, max = 100) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        if (!progressBar || !valueMainDisplay) { return; }

        progressBar.style.animation = 'none';
        progressBar.offsetHeight;
        progressBar.style.animation = '';

        let numericValue = parseFloat(rawValue);
        if (isNaN(numericValue)) {
            numericValue = parseFloat(String(rawValue).replace(/[^0-9.-]/g, ''));
        }
        if (!isNaN(numericValue)) {
            valueMainDisplay.innerText = numericValue;
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
        } else {
            valueMainDisplay.innerText = rawValue;
        }
    }

    function switchTab(tabName, tabElement) {
        document.querySelectorAll('.tab-button').forEach(tab => tab.classList.remove('active'));
        document.querySelectorAll('.tab-panel').forEach(content => content.classList.remove('active'));
        if (tabElement) {
            tabElement.classList.add('active');
        }
        const targetPanel = document.getElementById('tab-content-' + tabName);
        if (targetPanel) {
            targetPanel.classList.add('active');
        }
    }

    function toggleCollapse(headerElement) {
        const content = headerElement.nextElementSibling;
        const toggleButton = headerElement.querySelector('.collapse-toggle');
        content.classList.toggle('collapsed');
        toggleButton.classList.toggle('collapsed');
        toggleButton.innerHTML = content.classList.contains('collapsed') ? '&#9660;' : '&#9650;'; // Down/Up arrow
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<div class='error-tip'>无法加载状态数据 (messages empty)</div>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.stat_data;
            if (!characterData) {
                document.getElementById('status-card').innerHTML = "<div class='error-tip'>无法加载状态数据 (characterData missing)</div>";
                return;
            }

            document.getElementById('current-time').innerText = SafeGetValue(characterData, '时间');
            document.getElementById('current-location').innerText = SafeGetValue(characterData, '地点');

            const characters = { 'zhaoninger': '赵宁儿', 'wangxuening': '王雪宁' };
            let firstActiveTab = null;
            let anyCharacterPresent = false;

            for (const key in characters) {
                const name = characters[key];
                const isPresent = SafeGetValue(characterData, `角色.${name}.是否在场`, false);
                const tab = document.getElementById(`tab-${key}`);
                const tabPanel = document.getElementById(`tab-content-${key}`);

                if (isPresent === true || isPresent === 'true') {
                    anyCharacterPresent = true;
                    if(tab) tab.style.display = 'block';
                    if (!firstActiveTab) firstActiveTab = key;

                    // --- 新增：在状态栏中实时计算好感度 ---
                    let affection = 0;
                    if (key === 'zhaoninger') {
                        const value = parseFloat(SafeGetValue(characterData, `角色.${name}.价值认同`, 0));
                        const sub = parseFloat(SafeGetValue(characterData, `角色.${name}.服从度`, 0));
                        const stockholm = parseFloat(SafeGetValue(characterData, `角色.${name}.斯德哥尔摩爱意`, 0));
                        const fear = parseFloat(SafeGetValue(characterData, `角色.${name}.恐惧度`, 0));
                        affection = (value * 0.6) + (sub * 0.2) + (stockholm * 0.2) - (fear * 0.1);
                    } else if (key === 'wangxuening') {
                        const dependency = parseFloat(SafeGetValue(characterData, `角色.${name}.依赖度`, 0));
                        const stockholm = parseFloat(SafeGetValue(characterData, `角色.${name}.斯德哥尔摩爱意`, 0));
                        const sub = parseFloat(SafeGetValue(characterData, `角色.${name}.服从度`, 0));
                        const fear = parseFloat(SafeGetValue(characterData, `角色.${name}.恐惧度`, 0));
                        affection = (dependency * 0.5) + (stockholm * 0.3) + (sub * 0.1) + (fear * 0.1);
                    }
                    affection = Math.max(0, Math.min(300, affection));
                    // --- 计算结束 ---

                    updateProgressBar(`${key}-affection-bar`, `${key}-affection`, null, affection, 0, 300);
                    updateProgressBar(`${key}-exposure-bar`, `${key}-exposure`, null, SafeGetValue(characterData, `角色.${name}.暴露度`), 0, 100);

                    document.getElementById(`${key}-top`).innerText = SafeGetValue(characterData, `角色.${name}.上衣`);
                    document.getElementById(`${key}-bottom`).innerText = SafeGetValue(characterData, `角色.${name}.下装`);
                    document.getElementById(`${key}-underwear`).innerText = SafeGetValue(characterData, `角色.${name}.内衣`);
                    document.getElementById(`${key}-footwear`).innerText = SafeGetValue(characterData, `角色.${name}.鞋袜`);
                    document.getElementById(`${key}-accessory`).innerText = SafeGetValue(characterData, `角色.${name}.配饰`);
                    document.getElementById(`${key}-action`).innerText = SafeGetValue(characterData, `角色.${name}.当前动作`);
                    document.getElementById(`${key}-thoughts`).innerText = SafeGetValue(characterData, `角色.${name}.内心话`);
                } else {
                    if(tab) tab.style.display = 'none';
                    if(tabPanel) tabPanel.classList.remove('active');
                }
            }

            const tabNav = document.getElementById('character-tab-nav');
            if (tabNav) {
                tabNav.style.display = anyCharacterPresent ? 'flex' : 'none';
            }

            const activeTab = document.querySelector('.tab-button.active');
            if (!activeTab || activeTab.style.display === 'none') {
                if (firstActiveTab) {
                    switchTab(firstActiveTab, document.getElementById(`tab-${firstActiveTab}`));
                }
            }

            document.querySelectorAll('.details-content').forEach(el => el.classList.add('collapsed'));
            document.querySelectorAll('.collapse-toggle').forEach(el => {
                el.classList.add('collapsed');
                el.innerHTML = '&#9660;';
            });

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<div class='error-tip'>状态栏加载出错: ${error.message}</div>`;
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
