entries.content:
{
  "name": "申城",
  "parent_realm": "无",
  "summary": "一座建立在浦江两岸的现代化国际都市，是财富、权力和欲望交织的中心。城市以浦江为界，鲜明地划分出代表着金融资本的新区与沉淀着工业历史的旧区，巨大的发展差异与阶层割裂并存于城市的每个角落。",
  "figures": [],
  "locations": [
    {
      "name": "陆家嘴金融区",
      "parent_realm": "申城",
      "summary": "申城的经济心脏与权力象征。这里高楼林立，街道宽阔洁净，充满了快节奏与精英主义氛围。白天是金融从业者的战场，夜晚则化为上流阶层的消费乐园，江边的景观餐厅与顶层酒吧俯瞰着整座城市的灯火。",
      "layout": "位于浦江以东，与旧区隔江相望。",
      "figures": [],
      "locations": [
        {
          "name": "环球金融中心",
          "summary": "金融区最高的建筑之一，众多跨国金融机构的总部所在地，出入此地被视为身份与成功的象征。",
          "layout": "位于金融区核心地带。"
        },
        {
          "name": "汤臣一品",
          "summary": "临江而建的顶级住宅区，以其高昂的价格和开阔的江景闻名。安保严密，是申城顶级富豪与权贵阶层的居住地之一，也是富二代们常用来举办私人派对的场所。",
          "layout": "位于金融区沿江地带。"
        },
        {
          "name": "国金中心商场",
          "summary": "汇集了全球所有一线奢侈品牌的顶级购物中心，是衡量财富与消费能力的标尺，也是赵宁儿这类女性向往和获取“赏赐”的地方。",
          "layout": "位于金融区交通枢纽上方，与多栋写字楼相连。"
        }
      ]
    },
    {
      "name": "虹口工业遗迹区",
      "parent_realm": "申城",
      "summary": "由旧工业区改造而成的城市区域，红砖厂房与老公房交错，弥漫着怀旧与现代艺术结合的气息。这里是城市普通工薪阶层与寻求低成本生活的中产文青的聚集地，生活节奏相对缓慢，充满了市井烟火气。",
      "layout": "位于浦江以西，城市北部。",
      "figures": [],
      "locations": [
        {
          "name": "虹口新村",
          "summary": "典型的上世纪建造的工人新村，由数排红砖外墙的六层居民楼构成。楼间距狭窄，空中布满杂乱的电线。社区内充满了浓厚的生活气息，但也显得陈旧与拥挤，是本地普通工薪家庭的典型居住区。",
          "figures": [
            { "name": "赵宁儿", "summary": "其原生家庭居住于此。" },
            { "name": "赵宁儿的父母", "summary": "小区的长期居民，普通的工薪阶层退休人员。" }
          ],
          "locations": [
            { "name": "小区门口的菜市场", "summary": "一个半露天的菜市场，清晨和傍晚时分人声鼎沸，是小区居民日常社交和获取信息的重要场所。", "layout": "位于新村主入口处。" },
            { "name": "赵宁儿的家", "summary": "一套位于高楼层的两居室，内部是过时的装修风格，空间被各种生活杂物填满，承载着一个普通家庭的全部历史。", "layout": "位于小区内一栋楼的五层。" }
          ]
        },
        {
          "name": "城东小区",
          "summary": "一个建于本世纪初的普通住宅小区。楼体外观尚可，但内部设施已显陈旧。小区内绿化稀疏，公共空间常被老年居民占据。邻里之间彼此熟识，关系紧密但也意味着个人隐私的缺失，充满了压抑而琐碎的生活气息。",
          "figures": [
            { "name": "王雪宁", "summary": "小区居民，居住在此处的一户家庭中。" },
            { "name": "张明德", "summary": "小区居民，王雪宁的丈夫。" },
            { "name": "王雪宁的婆婆", "summary": "小区居民，与王雪宁夫妇同住。" }
          ],
          "locations": [
            { "name": "小区花园", "summary": "位于小区中心的一小片空地，设有几个石凳和基础的健身器材，是老年人闲聊和孩子们玩耍的主要场所。", "layout": "位于小区中心。" },
            { "name": "王雪宁的家", "summary": "一套标准的两室一厅户型，装修风格停留在十年前，空间因堆积的杂物而显得拥挤。客厅的电视常年播放着新闻或家庭伦理剧。", "layout": "位于小区内一栋楼的中层。" }
          ]
        }
      ]
    },
    {
      "name": "静安高端生活区",
      "parent_realm": "申城",
      "summary": "申城的传统富人区与时尚消费中心。这里街道整洁，梧桐成荫，汇集了众多历史保护建筑、奢侈品商店与米其林餐厅。区域内安保严密，氛围优雅而排外，是老钱家族与新贵阶层共同的社交舞台与生活空间。",
      "layout": "位于浦江以西，城市中心区域。",
      "figures": [],
      "locations": [
        {
          "name": "恒隆广场",
          "summary": "顶级奢侈品购物中心的代表，不仅是消费场所，更是身份的展演舞台。其内部的VIP休息室是富二代圈子消遣和社交的常用地点。",
          "layout": "位于该区域的商业核心地带。"
        },
        {
          "name": "外滩华尔道夫酒店",
          "summary": "由历史建筑改造的豪华酒店，以其复古的装修风格和高规格的服务闻名。顶层的酒吧是观赏浦江夜景的绝佳位置，也是富二代们炫耀财富、款待玩物的场所。",
          "layout": "位于区域东侧，紧邻外滩。"
        },
        {
          "name": "雍福会",
          "summary": "隐藏在老洋房中的私人会所，实行严格的会员制。内部装饰典雅，私密性高，是进行秘密商务洽谈和私人高端派对的首选之地。",
          "layout": "位于区域西南侧的幽静街道内。"
        },
        {
          "name": "城东幼儿园",
          "summary": "一所收费中等的私立幼儿园，因其相对体面的教学环境而吸引了周边中产家庭。这是赵宁儿维持其表面清纯形象的工作场所。",
          "layout": "位于区域东部边缘，与虹口区交界。"
        }
      ]
    },
    {
      "name": "闸北城中村",
      "parent_realm": "申城",
      "summary": "被摩天楼与高架桥包围的城市孤岛。这里建筑密集无序，狭窄的巷道终日难见阳光，空气中混合着食物、潮湿与生活的复杂气味。它是外来务工者与城市边缘群体的庇护所，秩序混乱但生命力旺盛，与周围的繁华世界形成一道无形的墙壁。",
      "layout": "位于浦江以西，新旧区域的交界地带，被城市主干道与铁路分割。",
      "figures": [],
      "locations": [
        {
          "name": "闸北社区医院",
          "summary": "一所服务于城中村及周边区域的社区级医院。建筑陈旧，墙壁上贴满了各类健康宣传海报。因人手和设备有限，只能处理常见的头疼脑热，环境嘈杂，弥漫着消毒水和草药混合的气味。",
          "figures": [
            { "name": "王雪宁", "summary": "该医院的一名护士。" }
          ],
          "locations": [
            { "name": "门诊大厅", "summary": "空间狭小，总是挤满了候诊的病人。一排排的硬塑料座椅上坐满了表情疲惫的居民，叫号系统的声音与病人的咳嗽声交织在一起。", "layout": "位于医院一层入口处。" },
            { "name": "护士站", "summary": "一个半开放式的工作台，台面上堆满了病历和药品。护士们在这里进行配药、登记和应答病人的问询，工作节奏紧张而重复。", "layout": "位于门诊大厅的一侧。" }
          ]
        },
        {
          "name": "北站垃圾中转站",
          "summary": "一个大型的半露天垃圾处理站，负责收集附近数个街区的垃圾。巨大的压缩机日夜轰鸣，散发着浓烈的气味，是城市光鲜背后的阴影。",
          "layout": "位于城中村最北侧，紧邻铁路。"
        }
      ]
    }
  ]
}

